const body = $input.first().json.body || $input.first().json;
const data = body.data || body;
const key = data.key || {};
const remoteJid = key.remoteJid || '';
const phone = remoteJid.replace('@s.whatsapp.net','').replace('@g.us','');

if (key.fromMe) return [];

const message = data.message || {};
const messageType = data.messageType || 'unknown';
let textContent = '';
if (messageType === 'conversation') textContent = message.conversation || '';
else if (messageType === 'extendedTextMessage') textContent = (message.extendedTextMessage||{}).text || '';
else if (messageType === 'audioMessage') textContent = '[رسالة صوتية]';
else textContent = message.conversation || message.text || '';

// Normalize
// تحويل "X أيام" الرقمي → (X-1) ليالي
textContent = textContent.replace(/(\d+)\s*(ايام|أيام|يوم)/g, (m, d) => {
  const nights = parseInt(d) - 1;
  return nights + ' ليالي';
});
textContent = textContent.replace(/اسبوعين|أسبوعين/g, '14 ليالي');
textContent = textContent.replace(/اسبوع|أسبوع/g, '7 ليالي');
textContent = textContent.replace(/عشر ايام|عشرة ايام|عشر أيام|عشرة أيام/g, '9 ليالي');
textContent = textContent.replace(/خمسة ايام|خمس ايام|خمسة أيام/g, '4 ليالي');
textContent = textContent.replace(/ستة ايام|ست ايام/g, '5 ليالي');

const MANAGER_PHONE = '380936582617';
const isManager = (phone === MANAGER_PHONE);
const SB = 'https://xfibcjhshpmqkrhlpsoa.supabase.co/rest/v1';
const KEY = 'eyJ-REDACTED-SERVICE-ROLE';
const h = { 'apikey': KEY, 'Authorization': 'Bearer '+KEY, 'Content-Type': 'application/json' };

let isNew = false, lead = null;
try {
  const r = await this.helpers.httpRequest({ method:'GET', url:`${SB}/leads?phone=eq.${phone}&limit=1`, headers:h });
  if (r.length > 0) {
    lead = r[0];
    await this.helpers.httpRequest({ method:'PATCH', url:`${SB}/leads?phone=eq.${phone}`, headers:{...h,'Prefer':'return=minimal'}, body:{ last_contact: new Date().toISOString(), updated_at: new Date().toISOString() } });
  } else {
    isNew = true;
    if (!isManager) {
      const r2 = await this.helpers.httpRequest({ method:'POST', url:`${SB}/leads`, headers:{...h,'Prefer':'return=representation'}, body:{ phone, stage:'new', assigned_to:'bot', source:'direct', last_contact: new Date().toISOString() } });
      lead = r2[0] || null;
    }
  }
} catch(e) {}

if (!isManager) {
  try { await this.helpers.httpRequest({ method:'POST', url:`${SB}/conversations`, headers:{...h,'Prefer':'return=minimal'}, body:{ phone, role:'user', message:textContent } }); } catch(e) {}
}

let chatHistory = '';
try {
  const msgs = await this.helpers.httpRequest({ method:'GET', url:`${SB}/conversations?phone=eq.${phone}&order=id.asc&limit=30`, headers:h });
  chatHistory = msgs.map(m => (m.role==='user'?'العميل':'ليلى')+': '+m.message).join('\n');
} catch(e) {}

let managerInstructions = '';
try {
  const inst = await this.helpers.httpRequest({ method:'GET', url:`${SB}/manager_instructions?active=eq.true&order=created_at.desc&limit=20`, headers:h });
  if (inst.length>0) managerInstructions = inst.map(i=>'- '+i.instruction).join('\n');
} catch(e) {}

let context = '';
if (isManager) context = 'هذا المدير أبو أمير — عامليه كمديرك.';
else if (isNew) context = 'عميل جديد — عرّفي نفسك "أنا ليلى من أركاديا للسياحة".';
else context = 'عميل سابق — لا تعرّفي نفسك.';
if (lead) {
  if (lead.name) context += ` اسمه: ${lead.name}.`;
  if (lead.destination) context += ` الوجهة: ${lead.destination}.`;
}

// كشف لغة العميل
const enWords = (textContent.match(/[a-zA-Z]{3,}/g) || []).length;
const totalWords = textContent.trim().split(/\s+/).length;
const customerLanguage = (enWords / Math.max(totalWords, 1)) > 0.5 ? 'en' : 'ar';

return [{ json: { phone, remoteJid, textContent, customerLanguage, isManager, isNew, lead, chatHistory, managerInstructions, context } }];

const prev = $input.first().json;
const curMsg = prev.textContent || '';
const OR_KEY = 'REDACTED_API_KEY';
const PE_URL = 'https://n8n.arcadia-tour.cloud/webhook/pricing-engine';
const SB = 'https://xfibcjhshpmqkrhlpsoa.supabase.co/rest/v1';
const SB_KEY = 'eyJ-REDACTED-SERVICE-ROLE';

let messages = [...prev.requestBody.messages];
let capturedAdults = 0;
let capturedChildrenAges = [];
const tools = prev.requestBody.tools;
let finalResponse = '';
// ── مساعدات من المحادثة ─────────────────────────────────────────────────────
const chatHist = prev.chatHistory || '';

// استخرج الليالي من المحادثة (آخر رقم قبل ليال)
function extractNightsFromHistory(hist) {
  const m = hist.match(/(\d+)\s*ليال/g);
  if (m && m.length > 0) {
    const last = m[m.length - 1].match(/(\d+)/);
    if (last) return parseInt(last[1]);
  }
  return null;
}

// استخرج أسماء الفنادق المعروضة سابقاً
function extractShownHotels(hist) {
  const hotels = [];
  // تنسيق 1: "🏨 Hotel Name ⭐" (قديم)
  const m1 = hist.matchAll(/🏨\s+([A-Za-z][^⭐\n]+?)\s*⭐/g);
  for (const m of m1) { const n=m[1].trim(); if(n&&!hotels.includes(n)) hotels.push(n); }
  // تنسيق 2: "**: Hotel Name ⭐" (جديد)
  const m2 = hist.matchAll(/\*\*[^*]+\*\*:?\s*([A-Za-z][A-Za-z0-9 &'\-]+)\s*⭐/g);
  for (const m of m2) { const n=m[1].trim(); if(n&&!hotels.includes(n)) hotels.push(n); }
  // تنسيق 3: "فندق: Hotel Name ⭐"
  const m3 = hist.matchAll(/فندق[:\s]+([A-Za-z][A-Za-z0-9 &'\-]+)\s*⭐/g);
  for (const m of m3) { const n=m[1].trim(); if(n&&!hotels.includes(n)) hotels.push(n); }
  return hotels;
}

const ctxNights = extractNightsFromHistory(chatHist);
const shownHotels = extractShownHotels(chatHist);
// ─────────────────────────────────────────────────────────────────────────────


// ── Pre-loop: فحص الأطفال قبل أي API call ──────────────────────────────
const childKeywords = /طفل|أطفال|ولد|أولاد|بنت|بنات|صغار|بزران|baby|child|children|kids/i;
const agePattern = /\b([0-9]+)\s*(سن|سنة|سنوات|عمر|year|yr)/i;
const fullText = chatHist + ' ' + (prev.textContent||'');
const hasChildren = childKeywords.test(fullText);

// لو البوت سأل عن الأعمار في أي رسالة سابقة (مش بس الأخيرة) + فيه رقم بعدها → أعمار مُعطاة
const botEverAskedAges = chatHist.indexOf('أعمار') >= 0 || chatHist.indexOf('الأبطال') >= 0;
// فحص: هل في رقم في chatHistory بعد سؤال الأعمار؟
const agesQuestionIdx = Math.max(chatHist.indexOf('أعمار'), chatHist.indexOf('الأبطال'));
const textAfterAgesQ = agesQuestionIdx >= 0 ? chatHist.slice(agesQuestionIdx) : '';
const digitsAfterAgesQ = /[0-9]/.test(textAfterAgesQ);

const hasAges = agePattern.test(fullText) || (botEverAskedAges && digitsAfterAgesQ);

if (hasChildren && !hasAges) {
  finalResponse = 'الله يحفظهم! عشان أحسب السعر الصح، كم أعمار الأبطال الصغار؟ لأن سياسة الفنادق والأسرة تعتمد على العمر 😊';
}
// ─────────────────────────────────────────────────────────────────────────────

let guardBreak = false;
let toolCallMade = false;
let lastPricingPackages = null;

// ── Pre-call: طلب أرخص/خيارات بعد رؤية الأسعار → استدعِ PE مباشرة ──────────
const histPricesPreCall = /\$[0-9]+|الباقة الاقتصادية/.test(chatHist);
// ═══ Pre-call MULTI: روسيا مدينتين أو كازاخستان + منتجع ═══
const destCodeCtx = (prev.context||{}).destination || '';
const isRussiaCtx = destCodeCtx === 'RU' || /روسيا|موسكو|سانت بطرسبرغ/i.test(chatHist);
const mscMatch = chatHist.match(/(\d+)\s*(?:ليالي?|ليلة)\s*(?:موسكو|moscow)/i);
const spbMatch = chatHist.match(/(\d+)\s*(?:ليالي?|ليلة)\s*(?:سانت|saint|بطرسبرغ)/i);
const isConsentMsg = /^(?:نعم|أيوه|موافق|تمام|اعرض|أعرض|yes|ايوه|أكيد)/.test((prev.textContent||'').trim());
const hasCircularHint = /دائري|نفس المدينة|دائرية|نفس الوصول/.test(chatHist + ' ' + (prev.textContent||''));

if (isRussiaCtx && mscMatch && spbMatch && !histPricesPreCall && (isConsentMsg || hasCircularHint)) {
  // condition TRUE
  const mscN = parseInt(mscMatch[1]);
  const spbN = parseInt(spbMatch[1]);
  const circular = hasCircularHint || true; // افترض دائري إذا لم يُحدد
  const adults_mc = prev.paxAdults || 2;
  const segs = [
    {city:'Moscow', nights:mscN, tours:Math.max(mscN-1,1)},
    {city:'Saint Petersburg', nights:spbN, tours:Math.max(spbN-1,1)}
  ];
  if (circular) segs.push({city:'Moscow', nights:mscN, tours:Math.max(mscN-2,1)});

  try {
    const mcRes = await this.helpers.httpRequest({
      method:'POST', url:'https://n8n.arcadia-tour.cloud/webhook/pricing-engine',
      headers:{'Content-Type':'application/json'},
      body: JSON.stringify({destination:'RU', adults:adults_mc, segments:segs})
    });
    if (!mcRes.ok || !mcRes.packages || mcRes.packages.length === 0) {
      finalResponse = 'MULTI_NOPKG: ok=' + mcRes.ok + ' pkgs=' + (mcRes.packages?mcRes.packages.length:'null') + ' multiCity=' + mcRes.multiCity;
    }
    if (mcRes.ok && mcRes.packages && mcRes.packages.length > 0) {
      const totalN = segs.reduce((a,s)=>a+s.nights,0);
      const tierIcons = {eco:'🥉', silver:'🥈', gold:'🥇'};
      let msg = 'عندي لك باقات روسيا 🇷🇺 — ' + totalN + ' ليالي (' + (totalN+1) + ' أيام):\n\n';
      for (const pkg of mcRes.packages) {
        msg += (tierIcons[pkg.tier]||'🏷') + ' *الباقة ' + pkg.tierAr + '* — *$' + pkg.totalUSD.toLocaleString() + '*\n';
        for (const stop of pkg.stops) {
          const cAr = stop.city==='Moscow'?'موسكو':stop.city==='Saint Petersburg'?'سان بطرسبرغ':stop.city;
          msg += '   📍 ' + cAr + ' — ' + stop.nights + ' ليالي: ' + stop.hotelName + ' ⭐' + stop.stars + '\n';
        }
        msg += '\n';
      }
      msg += '✅ يشمل: فندق + إفطار + استقبال/توديع + سيارة خاصة + جولات + 🚂 تذاكر القطار\n⚠️ السعر حسب التوفر';
      finalResponse = msg;
      toolCallMade = true;
    }
  } catch(e) { finalResponse = 'MULTI_ERR: ' + e.message; }
}

// ═══ Pre-call KZ RESORT: كازاخستان + أوي قورقاي ═══
const isKZCtx = /قازاقستان|كازاخستان|ألماتي|almaty/i.test(chatHist);
const hasResortCtx = /منتجع|أكواخ|أوي|قورقاي|resort/i.test(chatHist);

if (isKZCtx && hasResortCtx && !histPricesPreCall && !finalResponse) {
  // استخرج توزيع الليالي: "3 ألماتي، 2 منتجع، 2 ألماتي" أو "3 ليالي ألماتي 2 منتجع 2 ألماتي"
  const kzHistory = chatHist + ' ' + (prev.textContent||'');

  // أنماط الليالي
  const almN1 = kzHistory.match(/(\d+)\s*(?:ليالي?|ليلة|يوم|أيام)?\s*(?:ألماتي|almaty)/i);
  const resN  = kzHistory.match(/(\d+)\s*(?:ليالي?|ليلة|يوم|أيام)?\s*(?:منتجع|أكواخ|أوي|resort)/i);
  const almN2M = [...kzHistory.matchAll(/(\d+)\s*(?:ليالي?|ليلة|يوم|أيام)?\s*(?:ألماتي|almaty)/gi)];

  const alm1 = almN1 ? parseInt(almN1[1]) : null;
  const resN_val = resN ? parseInt(resN[1]) : null;
  // الـ 2nd ألماتي: آخر match غير الأول
  const alm2 = almN2M.length >= 2 ? parseInt(almN2M[almN2M.length-1][1]) : alm1;

  const isConsent = /^(?:نعم|أيوه|موافق|تمام|اعرض|أعرض|yes|ايوه|أكيد)/.test((prev.textContent||'').trim());

  if (alm1 && resN_val && isConsent) {
    const adults_kz = prev.paxAdults || 2;
    const segsKZ = [
      {city:'Almaty', nights:alm1, tours:Math.max(alm1-1, 1)},
      {city:'Almaty Region', nights:resN_val, tours:0},
      {city:'Almaty', nights:alm2||alm1, tours:Math.max((alm2||alm1)-1, 1)}
    ];

    try {
      const kzRes = await this.helpers.httpRequest({
        method:'POST', url:'https://n8n.arcadia-tour.cloud/webhook/pricing-engine',
        headers:{'Content-Type':'application/json'},
        body: JSON.stringify({destination:'KZ', adults:adults_kz, segments:segsKZ})
      });
      if (kzRes.ok && kzRes.packages && kzRes.packages.length > 0) {
        const totalN = segsKZ.reduce((a,s)=>a+s.nights,0);
        const tierIcons = {eco:'🥉', silver:'🥈', gold:'🥇'};
        let msg = 'عندي لك باقات كازاخستان 🇰🇿 — ' + totalN + ' ليالي (' + (totalN+1) + ' أيام):\n\n';
        for (const pkg of kzRes.packages) {
          msg += (tierIcons[pkg.tier]||'🏷') + ' *الباقة ' + pkg.tierAr + '* — *$' + pkg.totalUSD.toLocaleString() + '*\n';
          for (const stop of pkg.stops) {
            const cAr = stop.city==='Almaty'?'ألماتي':stop.city==='Almaty Region'?'منتجع أوي قورقاي 🏕️':stop.city;
            msg += '   📍 ' + cAr + ' — ' + stop.nights + ' ليالي: ' + stop.hotelName + ' ⭐' + stop.stars + '\n';
          }
          msg += '\n';
        }
        msg += '✅ يشمل: فندق + إفطار + استقبال/توديع + سيارة خاصة + جولات\n⚠️ السعر حسب التوفر';
        finalResponse = msg;
        toolCallMade = true;
      }
    } catch(e) { finalResponse = 'KZ_ERR: ' + e.message; }
  }
}
// ═══════════════════════════════════════════════════════════════════
// UNIFIED STATE MACHINE — يحل محل State Merge + Pre-call SINGLE
// المبدأ: كود يقرر، AI يصوغ فقط
// ═══════════════════════════════════════════════════════════════════
if (!finalResponse) {

  // ─── 1. استخرج رسائل العميل فقط (بدون نصوص البوت) ───
  const userLines = (chatHist.match(/العميل:[^\n]+/g) || []).map(l => l.replace('العميل:','').trim());
  userLines.push(curMsg);
  const userText = userLines.join(' ');
  // آخر رسالة من البوت (للـ consent check)
  const botLines = (chatHist.match(/ليلى:[^\n]+/g) || []);
  const lastBotMsg = botLines.length ? botLines[botLines.length-1].replace('ليلى:','').trim() : '';
  // آخر 3 رسائل من البوت
  const recentBotMsgs = botLines.slice(-3).map(l => l.replace('ليلى:','').trim()).join(' ');

  // ─── 2. SESSION RESET GUARD ───
  // إذا العميل بدأ بتحية جديدة → نتجاهل الـ state القديم
  const isGreeting = /^(السلام عليكم|هلا|مرحبا|مرحبأ|صباح|مساء|هاي|hi|hello|كيف|أهلا|اهلا)/i.test(curMsg.trim());
  // نص "البوت في حالة انتظار قديمة" = آخر رد بوت هو سؤال consent ولكن بلا رد مباشر من العميل بعده
  const botWasAwaitingConsent = /تحب أعرض|تبي نعرض|تحب نشوف|تحب تشوف|تحب نكمل/i.test(lastBotMsg);
  const sessionReset = isGreeting && botWasAwaitingConsent;
  console.log('[SESSION] isGreeting=' + isGreeting + ' botAwaitingConsent=' + botWasAwaitingConsent + ' reset=' + sessionReset);

  // إذا reset → هذه جلسة جديدة، اتركها للـ AI بدون Pre-call
  if (!sessionReset) {

    // ─── 3. استخراج الـ State من رسائل العميل فقط ───

    // Destination (آخر ذكر يفوز)
    let smDest = null;
    if (/روسيا|russia/i.test(userText)) smDest = 'RU';
    if (/كازاخستان|قازاقستان|kazakhstan/i.test(userText)) smDest = 'KZ';
    // مدن تُحدد الوجهة
    if (/موسكو|moscow|سانت بطرسبرغ|سانت|saint|petersburg/i.test(userText)) smDest = 'RU';
    if (/ألماتي|almaty|الماتي/i.test(userText)) smDest = 'KZ';

    // City (آخر ذكر يفوز)
    let smCity = null;
    if (smDest === 'RU') {
      const mosIdx = userText.search(/موسكو|moscow/i);
      const spbIdx = userText.search(/سانت|saint|petersburg/i);
      if (mosIdx >= 0 || spbIdx >= 0) {
        // ابحث عن الأخير بالمقارنة العكسية
        const mosLast = Math.max(...[...userText.matchAll(/موسكو|moscow/gi)].map(m => m.index), -1);
        const spbLast = Math.max(...[...userText.matchAll(/سانت|saint|petersburg/gi)].map(m => m.index), -1);
        smCity = (spbLast > mosLast) ? 'Saint Petersburg' : 'Moscow';
      }
    } else if (smDest === 'KZ') {
      const hasResort = /منتجع|أكواخ|أوي قورقاي/i.test(userText);
      const hasAlmaty = /ألماتي|almaty|الماتي/i.test(userText);
      if (hasResort && hasAlmaty) {
        // آخر ذكر يفوز
        const aLast = Math.max(...[...userText.matchAll(/ألماتي|almaty|الماتي/gi)].map(m => m.index), -1);
        const rLast = Math.max(...[...userText.matchAll(/منتجع|أكواخ|أوي قورقاي/gi)].map(m => m.index), -1);
        smCity = (rLast > aLast) ? 'resort' : 'Almaty';
      } else if (hasResort) smCity = 'resort';
      else if (hasAlmaty) smCity = 'Almaty';
    }

    // Nights (آخر ذكر)
    let smNights = null;
    const nightsMatches = [...userText.matchAll(/(\d+)\s*(?:لي[لا]لي|ليلة)/gi)];
    const daysMatches   = [...userText.matchAll(/(\d+)\s*(?:يوم|أيام|ايام)/gi)];
    if (nightsMatches.length) smNights = parseInt(nightsMatches[nightsMatches.length-1][1]);
    else if (daysMatches.length) smNights = parseInt(daysMatches[daysMatches.length-1][1]) - 1;
    // "اسبوع" = 7 ليالي
    if (!smNights && /اسبوع|أسبوع/i.test(userText)) smNights = 7;

    // Adults (آخر ذكر)
    let smAdults = null;
    if (/شخص واحد|شخص فقط/i.test(userText)) smAdults = 1;
    else if (/شخصين/i.test(userText)) smAdults = 2;
    else if (/ثلاثة أشخاص|3 أشخاص|3 بالغ/i.test(userText)) smAdults = 3;
    const adultsMatch = userText.match(/(\d+)\s*(?:أشخاص|شخص|بالغين|بالغ|adults?)/);
    if (adultsMatch) smAdults = parseInt(adultsMatch[1]);

    // Children
    const smHasKids = /أطفال|طفل|طفلة|children|child/i.test(userText);
    let smChildrenAges = [];
    if (smHasKids) {
      const agesAll = [];
      const m1 = userText.match(/(\d+)\s*(?:سنة|سنوات|years?)/g) || [];
      m1.forEach(s => { const n=parseInt(s); if(n>0&&n<18) agesAll.push(n); });
      const m2 = userText.match(/[وand،,]\s*(\d+)(?=\s*(?:سنة|سنوات|عام|years?))/g) || [];
      m2.forEach(s => { const n=parseInt(s.replace(/[^\d]/g,'')); if(n>0&&n<18&&!agesAll.includes(n)) agesAll.push(n); });
      const m3 = userText.match(/عمر[هاه]?\s*(\d+)/g) || [];
      m3.forEach(s => { const n=parseInt(s.replace(/[^\d]/g,'')); if(n>0&&n<18&&!agesAll.includes(n)) agesAll.push(n); });
      smChildrenAges = [...new Set(agesAll)];
    }
    const smKidsOk = !smHasKids || smChildrenAges.length > 0;

    // Tours (KZ فقط)
    let smTours = null;
    if (/مع الجولات|مع جولات/i.test(userText)) smTours = true;
    else if (/بدون جولات/i.test(userText)) smTours = false;
    else if (/^(نعم|ايوه|اوك|ok|yes|مع)$/i.test(curMsg.trim()) && /جولات/i.test(recentBotMsgs)) smTours = true;
    else if (/^(لا|بدون|no)$/i.test(curMsg.trim()) && /جولات/i.test(recentBotMsgs)) smTours = false;

    // Multi-city check (رسائل العميل فقط)
    const smMultiCity = /موسكو.*سانت|سانت.*موسكو|المدينتين/i.test(userText) ||
                        /منتجع.*ألماتي|ألماتي.*منتجع/i.test(userText);

    console.log('[SM STATE] dest=' + smDest + ' city=' + smCity + ' nights=' + smNights + ' adults=' + smAdults + ' tours=' + smTours + ' kids=' + smHasKids + ' kidsOk=' + smKidsOk + ' multi=' + smMultiCity);

    // ─── 4. REQUIRED FIELDS GATE ───
    const smNeedsCity   = smDest && !smCity && !smMultiCity;
    const smNeedsNights = smDest && !smNights;
    const smNeedsAdults = smDest && !smAdults;
    const smNeedsKids   = smDest && smHasKids && !smKidsOk;
