        tours: s.tours !== undefined ? s.tours :
               (s.city === 'Almaty Region' ? 0 : Math.max((s.nights||3)-1, 1))
      }));

      try {
        const mcResult = await this.helpers.httpRequest({
          method: 'POST',
          url: 'https://n8n.arcadia-tour.cloud/webhook/pricing-engine',
          headers: {'Content-Type': 'application/json'},
          body: JSON.stringify({ destination: dest_mc, adults: adults_mc, childrenAges: childrenAges_mc, segments: finalSegs })
        });

        toolCallMade = true;
        capturedAdults = adults_mc;
        capturedChildrenAges = childrenAges_mc;

        if (!mcResult.ok || !mcResult.packages || mcResult.packages.length === 0) {
          toolResult = 'لا توجد باقات متاحة حالياً لهذه الرحلة.';
        } else {
          const destName = dest_mc === 'RU' ? 'روسيا 🇷🇺' : 'كازاخستان 🇰🇿';
          const totalNights = finalSegs.reduce((a, s) => a + s.nights, 0);
          const trainNote = dest_mc === 'RU' ? '🚂 تذاكر القطار مشمولة\n' : '';
          const tierIcons = {eco:'🥉', silver:'🥈', gold:'🥇'};

          let msg = 'عندي لك باقات ' + destName + ' — ' + totalNights + ' ليالي (' + (totalNights+1) + ' أيام):\n\n';
          for (const pkg of mcResult.packages) {
            const icon = tierIcons[pkg.tier] || '🏷';
            msg += icon + ' *الباقة ' + pkg.tierAr + '* — *$' + pkg.totalUSD.toLocaleString() + '*\n';
            for (const stop of pkg.stops) {
              const cityAr = stop.city==='Moscow'?'موسكو': stop.city==='Saint Petersburg'?'سان بطرسبرغ': stop.city==='Almaty'?'ألماتي': stop.city==='Almaty Region'?'منتجع أوي قورقاي': stop.city;
              msg += '   📍 ' + cityAr + ' — ' + stop.nights + ' ليالي | ' + stop.hotelName + ' ⭐' + stop.stars + '\n';
            }
            msg += '\n';
          }
          msg += '✅ يشمل: فندق + إفطار + استقبال/توديع + سيارة خاصة + جولات\n';
          msg += trainNote;
          msg += `⚠️ السعر حسب التوفر`;

          toolResult = msg;
          lastPricingPackages = mcResult.packages;
          effectiveHasPrices = true;
        }
      } catch(e) {
        toolResult = 'خطأ تقني: ' + e.message;
      }
    }

    if (fn === 'get_program') {
      let gp_dest = args.destination || (ctxDest === 'KZ' ? 'Kazakhstan' : ctxDest === 'RU' ? 'Russia' : null);
      if (!gp_dest) {
        if (/كازاخستان/i.test(chatHist)) gp_dest = 'Kazakhstan';
        else if (/روسيا|موسكو/i.test(chatHist)) gp_dest = 'Russia';
        else gp_dest = 'Kazakhstan';
      }
      // استخرج الليالي من chatHistory إذا ctxNights فارغ
      let gp_nights = ctxNights || parseInt(args.nights) || 0;
      if (!gp_nights) {
        const nightsMatch = chatHist.match(/(\d+)\s*لي[لا]لي/);
        if (nightsMatch) gp_nights = parseInt(nightsMatch[1]);
      }
      if (!gp_nights) gp_nights = 6; // fallback
      const sbGpUrl = 'https://xfibcjhshpmqkrhlpsoa.supabase.co/rest/v1/itineraries?country=eq.' + encodeURIComponent(gp_dest) + '&notes_ar=eq.nights%3A' + gp_nights + '&order=day_number.asc'; // %3A = encoded :
      let progRows = [];
      console.log('get_program called: dest=' + gp_dest + ' nights=' + gp_nights + ' url=' + sbGpUrl);
      try {
        progRows = await this.helpers.httpRequest({
          method: 'GET', url: sbGpUrl,
          headers: {'apikey': supabaseKey, 'Authorization': 'Bearer ' + supabaseKey}
        });
        console.log('get_program rows:', progRows ? progRows.length : 'null');
      } catch(e) { console.log('get_program error:', e.message); progRows = []; }
      if (progRows && progRows.length > 0) {
        const gpFlag = gp_dest === 'Kazakhstan' ? '🇰🇿' : '🇷🇺';
        const gpName = gp_dest === 'Kazakhstan' ? 'كازاخستان' : 'روسيا';
        let prog = '📋 *البرنامج السياحي — ' + gpName + ' ' + gpFlag + '*\n*' + (gp_nights+1) + ' أيام / ' + gp_nights + ' ليالي*\n\n';
        for (const day of progRows) {
          const acts = day.description_ar.split('\n').filter(Boolean).map(a => '   • ' + a).join('\n');
          prog += '🗓️ *اليوم ' + day.day_number + ':*\n' + acts + '\n\n';
        }
        prog += '📌 البرنامج قابل للتعديل حسب الرغبة والمواسم.';
        finalResponse = prog;
      } else {
        finalResponse = 'البرنامج التفصيلي راح يوصلك بعد تأكيد الحجز إن شاء الله 😊';
      }
      toolCallMade = true;
    } else if (fn === 'save_manager_instruction') {
      if (!prev.isManager) { result = 'ممنوع — فقط المدير يقدر يعطي تعليمات.'; messages.push({role:'tool',tool_call_id:tc.id,content:result}); continue; }
      try {
        await this.helpers.httpRequest({ method:'POST', url:`${SB}/manager_instructions`,
          headers:{'apikey':SB_KEY,'Authorization':'Bearer '+SB_KEY,'Content-Type':'application/json','Prefer':'return=minimal'},
          body:{ instruction:args.instruction, active:true, created_at:new Date().toISOString() }
        });
        result = 'تم حفظ التعليمة.';
      } catch(e) { result = 'فشل الحفظ.'; }
    }

    messages.push({ role:'tool', tool_call_id:tc.id, content:result });
  }
}



// ── Room Distribution Guard ──────────────────────────────────────────────────
// يُلحق جملة الغرف بكل عرض يحتوي أسعاراً
function calcRoomDistribution(adults, childrenAges) {
  if (!adults || adults <= 0) return null;

  // الأطفال +12 يُحسبون بالغين
  let effectiveAdults = adults;
  const childList = Array.isArray(childrenAges) ? childrenAges : [];
  let extraBeds = 0; // أطفال 6-11 → سرير إضافي في غرفة الوالدين

  for (const age of childList) {
    const a = parseInt(age);
    if (a >= 12) effectiveAdults++;
    else if (a >= 6) extraBeds++;
    // أقل من 6: مع الوالدين بدون سرير إضافي
  }

  let rooms = [];
  if (effectiveAdults === 1) rooms = ['غرفة مفردة'];
  else if (effectiveAdults === 2) rooms = ['غرفة مزدوجة'];
  else if (effectiveAdults === 3) rooms = ['غرفة ثلاثية'];
  else if (effectiveAdults === 4) rooms = ['غرفتان مزدوجتان'];
  else if (effectiveAdults === 5) rooms = ['غرفة ثلاثية + غرفة مزدوجة'];
  else if (effectiveAdults === 6) rooms = ['غرفتان ثلاثيتان'];
  else if (effectiveAdults === 7) rooms = ['غرفة ثلاثية + غرفتان مزدوجتان'];
  else if (effectiveAdults === 8) rooms = ['أربع غرف مزدوجة'];
  else rooms = [Math.ceil(effectiveAdults/2) + ' غرف مزدوجة'];

  let desc = rooms[0];
  if (extraBeds > 0) desc += ` + ${extraBeds === 1 ? 'سرير إضافي' : extraBeds + ' أسرة إضافية'} للأطفال`;

  const total = Math.ceil(effectiveAdults / 2) + (extraBeds > 0 ? 0 : 0);
  const roomCount = rooms[0].match(/[0-9]+/) ? rooms[0].match(/[0-9]+/)[0] : '1';

  return `\n\n🛏️ *توزيع الغرف:* الباقة تشمل ${desc} لضمان راحة جميع أفراد العائلة.`;
}

const peAdults = capturedAdults || 2;
const peChildrenAges = capturedChildrenAges || [];
const roomInfo = calcRoomDistribution(peAdults, peChildrenAges);

if (finalResponse && roomInfo && /\$[0-9]+/.test(finalResponse) && !finalResponse.includes('توزيع الغرف')) {
  finalResponse += roomInfo;
  console.log('🛏️ Room distribution appended:', roomInfo.trim());
}
