// ── Detector B: منع ذكر فنادق بدون tool call ────────────────────────
const knownHotelBrands = ["Radisson", "Marriott", "Hilton", "Novotel", "Ibis", "Mercure", "Sheraton", "Hyatt", "Crowne Plaza", "Holiday Inn", "InterContinental", "Four Seasons", "Ritz", "Park Inn", "Pullman", "Swissotel", "Kempinski", "Best Western", "Hampton", "DoubleTree", "Courtyard", "Renaissance", "Sofitel", "Mövenpick", "Movenpick", "Lotte", "Astana", "Rixos", "Wyndham", "Rotana", "Divan", "Ramada", "Park Hyatt", "Grand Hyatt", "Andaz", "Aloft", "W Hotel", "Westin", "Le Meridien", "Autograph", "Tribute", "Design Hotels", "Curio"];
const urlPattern = /https?:\/\/|www\.|\.(jpg|jpeg|png|webp|gif)/i;
const roomSizePattern = /\d+\s*(متر|م²|sqm|sq\.m|square)/i;

if (finalResponse) {
  const hadToolCall = messages.some(m => m.role === 'tool') || toolCallMade;
