const childrenByUser = /طفل|أطفال|ولد|أولاد|بنت|بنات|صغار|بزران|baby|child|children|kids/i.test(prev.textContent||'');
const aiAsksKids = /أعمار الأطفال|أعمار الأبطال|عدد الأطفال|معكم أطفال|في أطفال|عندكم أطفال|أطفال معاكم/i.test(finalResponse||'');
if (aiAsksKids && !childrenByUser) {
  // الـ AI يسأل عن أطفال والمستخدم ما ذكرهم → استبدل بـ consent
  finalResponse = 'تمام! عندي باقات شاملة 🌟 تحب أعرض لك التفاصيل والأسعار؟ 😊';
}

if (hasFakeItinerary) {
    finalResponse = 'البرنامج السياحي التفصيلي يوصلك بعد تأكيد الحجز 😊 أي باقة تفضل؟';
